/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { THEME_EXCEL_COLUMNS, THEME_EXCEL_SENSITIVE } from 'app/features/template/theme/model/theme-excel-columns';
import { take, map } from 'rxjs';
import { Theme } from 'app/features/template/theme/model/theme.model';
import { ThemeRepository } from 'app/features/template/theme/repository/theme-repository.service';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'theme-view-export-action',
  standalone: false,
  templateUrl: './theme-view-export-action.component.html',
})
export class ThemeViewExportActionComponent extends BaseExportAction<Theme> {
  protected readonly scope = 'template/theme';
  protected readonly repository = inject(ThemeRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ExportDefinition<Theme> = {
    name: 'template.theme',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: THEME_EXCEL_COLUMNS,
    sensitive: THEME_EXCEL_SENSITIVE,
    references: {
      tenant: {
        names: (refs) =>
          this.tenantRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
